solutions.naive:
class Solution:
    def splitArray(self, nums, k):
        def can_split(limit):
            pieces = 1
            total = 0
            for x in nums:
                if total + x > limit:
                    pieces += 1
                    total = 0
                total += x
            return pieces <= k

        for limit in range(max(nums), sum(nums) + 1):
            if can_split(limit):
                return limit
        return sum(nums)

solutions.better:
class Solution:
    def splitArray(self, nums, k):
        n = len(nums)
        if k >= n:
            return max(nums)
        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)
        prev = [0] + [prefix[i] for i in range(1, n + 1)]
        for parts in range(2, k + 1):
            curr = [0] * (n + 1)
            for i in range(1, n + 1):
                best = prefix[i]
                for cut in range(parts - 1, i):
                    best = min(best, max(prev[cut], prefix[i] - prefix[cut]))
                curr[i] = best
            prev = curr
        return prev[n]

