class Solution:
    def splitArray(self, nums, k):
        def pieces_allowed(limit):
            pieces = 1
            total = 0
            for x in nums:
                if total + x > limit:
                    pieces += 1
                    total = 0
                total += x
            return pieces

        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if pieces_allowed(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

